		const trimmed = mode.trim();
		if (MODE_GROUP.has(trimmed)) {
			modes.add(trimmed);
		}
	}

	if (!modes.size) {
		throw new Error('No valid modes');
	}
} else {
	for (const mode of MODE_GROUP) {
		modes.add(mode);
	}
}

